import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';

const ModifierCours = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [loading, setLoading] = useState(false);
  const [classes, setClasses] = useState([]);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    level: '',
    class_id: ''
  });

  // Récupérer le cours à modifier
  useEffect(() => {
    const fetchCourseAndClasses = async () => {
      try {
        const token = localStorage.getItem('token');
        
        // Récupérer le cours
        const courseResponse = await fetch(`http://localhost:5000/api/courses/${id}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });

        if (courseResponse.ok) {
          const result = await courseResponse.json();
          const course = result.data.course;
          setFormData({
            title: course.title,
            description: course.description,
            level: course.level,
            class_id: course.class_id
          });
        }

        // Récupérer les classes
        const classesResponse = await fetch('http://localhost:5000/api/classes', {
          headers: { 'Authorization': `Bearer ${token}` }
        });

        if (classesResponse.ok) {
          const classesData = await classesResponse.json();
          setClasses(classesData);
        }
      } catch (error) {
        console.error('Erreur:', error);
      }
    };

    fetchCourseAndClasses();
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`http://localhost:5000/api/courses/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });

      const result = await response.json();

      if (response.ok && result.success) {
        alert('✅ Cours modifié avec succès!');
        navigate('/mes-cours');
      } else {
        alert(`❌ Erreur: ${result.message}`);
      }
    } catch (error) {
      alert('❌ Erreur de connexion');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div style={{ padding: '20px' }}>
      <button onClick={() => navigate('/mes-cours')} style={{ marginBottom: '20px' }}>
        ← Retour
      </button>

      <h1>Modifier le Cours</h1>

      <form onSubmit={handleSubmit} style={{ maxWidth: '600px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label>Titre:</label>
          <input
            type="text"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '8px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Description:</label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleInputChange}
            rows="4"
            style={{ width: '100%', padding: '8px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Niveau:</label>
          <select
            name="level"
            value={formData.level}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '8px' }}
          >
            <option value="debutant">Débutant</option>
            <option value="intermediaire">Intermédiaire</option>
            <option value="avance">Avancé</option>
          </select>
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Classe:</label>
          <select
            name="class_id"
            value={formData.class_id}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '8px' }}
          >
            <option value="">Sélectionnez une classe</option>
            {classes.map(classe => (
              <option key={classe.id} value={classe.id}>
                {classe.name}
              </option>
            ))}
          </select>
        </div>

        <button 
          type="submit" 
          disabled={loading}
          style={{ 
            padding: '10px 20px', 
            backgroundColor: loading ? '#ccc' : '#3498db',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: loading ? 'not-allowed' : 'pointer'
          }}
        >
          {loading ? 'Modification...' : 'Modifier le Cours'}
        </button>
      </form>
    </div>
  );
};

export default ModifierCours;
